1	/**
2	 * Centralized Resend email service.
3	 *
4	 * All send functions return `true` on success, `false` on failure — they never
5	 * throw. This lets callers fire-and-forget without wrapping in try/catch.
6	 */
7	import { Resend } from "resend";
8	
9	// ---------------------------------------------------------------------------
10	// Types
11	// ---------------------------------------------------------------------------
12	
13	export interface EmailOptions {
14	  /** Display name in the From field (e.g. "Cool Store"). Defaults to shopDisplayName. */
15	  senderName?: string | null;
16	  /** Cached Shopify store display name (from ShopSettings.shopName). Falls back to myshopify slug. */
17	  shopDisplayName?: string | null;
18	  /** Reply-to email for customer-facing emails. If empty, no reply-to header is added. */
19	  replyTo?: string | null;
20	}
21	
22	// ---------------------------------------------------------------------------
23	// Client singleton
24	// ---------------------------------------------------------------------------
25	
26	let client: Resend | null = null;
27	
28	function getClient(): Resend | null {
29	  if (client) return client;
30	  const apiKey = process.env.RESEND_API_KEY;
31	  if (!apiKey) {
32	    console.warn("[email] RESEND_API_KEY not set — emails will be skipped");
33	    return null;
34	  }
35	  client = new Resend(apiKey);
36	  return client;
37	}
38	
39	function getRawFromEmail(): string {
40	  return process.env.RESEND_FROM_EMAIL || "noreply@example.com";
41	}
42	
43	function shopFallbackName(shop: string, options?: EmailOptions): string {
44	  return options?.shopDisplayName?.trim() || shop.replace(".myshopify.com", "");
45	}
46	
47	/**
48	 * Build the full From address with display name.
49	 *
50	 * - Custom sender name set:  "Cool Store via Pinzo <noreply@boldteq.app>"
51	 * - No custom name:          "cool-store via Pinzo <noreply@boldteq.app>"
52	 */
53	function buildFrom(shop: string, options?: EmailOptions): string {
54	  const displayName = options?.senderName?.trim() || shopFallbackName(shop, options);
55	  return `${displayName} via Pinzo <${getRawFromEmail()}>`;
56	}
57	
58	/**
59	 * Build optional reply_to field. Returns undefined when not configured
60	 * so it can be spread into the Resend payload without adding an empty header.
61	 */
62	function buildReplyTo(options?: EmailOptions): { reply_to: string } | Record<string, never> {
63	  const replyTo = options?.replyTo?.trim();
64	  if (replyTo) return { reply_to: replyTo };
65	  return {};
66	}
67	
68	/**
69	 * Wrap email body content in a branded layout with Pinzo logo header and store name.
70	 */
71	const APP_URL = process.env.SHOPIFY_APP_URL || "https://zip-code-checker-production-b1a0.up.railway.app";
72	
73	function emailLayout(storeName: string, body: string): string {
74	  return `
75	    <div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;background:#ffffff">
76	      <div style="padding:24px 24px 16px;border-bottom:1px solid #e5e7eb;text-align:center">
77	        <table cellpadding="0" cellspacing="0" border="0" style="margin:0 auto">
78	          <tr>
79	            <td style="vertical-align:middle;padding-right:10px">
80	              <img src="${APP_URL}/pinzo-logo.svg" alt="Pinzo" width="36" height="36" style="display:block;border-radius:8px" />
81	            </td>
82	            <td style="vertical-align:middle">
83	              <span style="font-size:20px;font-weight:700;color:#1a1a1a;letter-spacing:-0.3px">Pinzo</span>
84	            </td>
85	          </tr>
86	        </table>
87	        <p style="margin:8px 0 0;font-size:13px;color:#6b7280">${storeName}</p>
88	      </div>
89	      <div style="padding:24px">
90	        ${body}
91	      </div>
92	      <div style="padding:16px 24px;border-top:1px solid #e5e7eb;text-align:center">
93	        <p style="margin:0;font-size:12px;color:#9ca3af">Powered by <span style="color:#008060;font-weight:600">Pinzo</span></p>
94	      </div>
95	    </div>
96	  `;
97	}
98	
99	// ---------------------------------------------------------------------------
100	// 1. Waitlist Confirmation  (App → Customer)
101	// ---------------------------------------------------------------------------
102	
103	export async function sendWaitlistConfirmation(
104	  to: string,
105	  zipCode: string,
106	  shop: string,
107	  options?: EmailOptions,
108	): Promise<boolean> {
109	  const resend = getClient();
110	  if (!resend) return false;
111	
112	  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
113	
114	  try {
115	    await resend.emails.send({
116	      from: buildFrom(shop, options),
117	      to,
118	      subject: `You're on the waitlist — ${name}`,
119	      html: emailLayout(name, `
120	          <h2 style="margin:0 0 16px;color:#1a1a1a">You're on the waitlist!</h2>
121	          <p style="color:#374151;line-height:1.6">Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
122	          <p style="color:#6b7280;font-size:13px;margin-top:24px">— ${name}</p>
123	      `),
124	      text: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
125	      ...buildReplyTo(options),
126	    });
127	    return true;
128	  } catch (error) {
129	    console.error("[email] Failed to send waitlist confirmation:", error);
130	    return false;
131	  }
132	}
133	
134	// ---------------------------------------------------------------------------
135	// 2. Merchant Alert  (App → Merchant)
136	// ---------------------------------------------------------------------------
137	
138	export async function sendMerchantWaitlistAlert(
139	  to: string,
140	  customerEmail: string,
141	  zipCode: string,
142	  shop: string,
143	  options?: EmailOptions,
144	): Promise<boolean> {
145	  const resend = getClient();
146	  if (!resend) return false;
147	
148	  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
149	
150	  try {
151	    await resend.emails.send({
152	      from: buildFrom(shop, options),
153	      to,
154	      subject: `New waitlist signup: ${zipCode}`,
155	      html: emailLayout(name, `
156	          <h2 style="margin:0 0 16px;color:#1a1a1a">New waitlist signup</h2>
157	          <p style="color:#374151;line-height:1.6">A customer just joined the waitlist for ZIP code <strong>${zipCode}</strong>.</p>
158	          <table style="margin:16px 0;border-collapse:collapse">
159	            <tr><td style="padding:4px 12px 4px 0;color:#6b7280">Email</td><td style="color:#1a1a1a">${customerEmail}</td></tr>
160	            <tr><td style="padding:4px 12px 4px 0;color:#6b7280">ZIP Code</td><td style="color:#1a1a1a">${zipCode}</td></tr>
161	          </table>
162	          <p style="color:#6b7280;font-size:13px">You can manage the waitlist from your <strong>${name}</strong> admin dashboard.</p>
163	      `),
164	      text: `New waitlist signup\n\nA customer (${customerEmail}) just joined the waitlist for ZIP code ${zipCode}.\n\nManage the waitlist from your ${name} admin dashboard.`,
165	      ...buildReplyTo(options),
166	    });
167	    return true;
168	  } catch (error) {
169	    console.error("[email] Failed to send merchant waitlist alert:", error);
170	    return false;
171	  }
172	}
173	
174	// ---------------------------------------------------------------------------
175	// 3. ZIP Available Notification  (App → Customer)
176	// ---------------------------------------------------------------------------
177	
178	export async function sendZipAvailableNotification(
179	  to: string,
180	  zipCode: string,
181	  shop: string,
182	  shopUrl: string,
183	  options?: EmailOptions,
184	): Promise<boolean> {
185	  const resend = getClient();
186	  if (!resend) return false;
187	
188	  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
189	
190	  try {
191	    await resend.emails.send({
192	      from: buildFrom(shop, options),
193	      to,
194	      subject: `Great news! We now deliver to ${zipCode}`,
195	      html: emailLayout(name, `
196	          <h2 style="margin:0 0 16px;color:#1a1a1a">Great news!</h2>
197	          <p style="color:#374151;line-height:1.6">We're excited to let you know that delivery is now available to ZIP code <strong>${zipCode}</strong>.</p>
198	          <p style="margin-top:16px"><a href="${shopUrl}" style="display:inline-block;padding:12px 24px;background:#008060;color:#ffffff;text-decoration:none;border-radius:6px;font-weight:600;font-size:15px">Shop Now</a></p>
199	          <p style="color:#6b7280;font-size:13px;margin-top:24px">— ${name}</p>
200	      `),
201	      text: `Great news!\n\nDelivery is now available to ZIP code ${zipCode}. Visit ${shopUrl} to place your order.\n\n— ${name}`,
202	      ...buildReplyTo(options),
203	    });
204	    return true;
205	  } catch (error) {
206	    console.error("[email] Failed to send ZIP available notification:", error);
207	    return false;
208	  }
209	}
