211	// ---------------------------------------------------------------------------
212	// 4. Test Email  (Settings page)
213	// ---------------------------------------------------------------------------
214	
215	export async function sendTestEmail(
216	  to: string,
217	  options?: EmailOptions,
218	  shop?: string,
219	): Promise<boolean> {
220	  const resend = getClient();
221	  if (!resend) return false;
222	
223	  const name = options?.senderName?.trim() || (shop ? shopFallbackName(shop, options) : "Your Store");
224	
225	  try {
226	    await resend.emails.send({
227	      from: buildFrom(shop || "test-store.myshopify.com", options),
228	      to,
229	      subject: "Pinzo — Test Email",
230	      html: emailLayout(name, `
231	          <h2 style="margin:0 0 16px;color:#1a1a1a">Test email received!</h2>
232	          <p style="color:#374151;line-height:1.6">Your email integration is working correctly.</p>
233	          <p style="margin-top:16px;color:#374151"><strong>From:</strong> ${name} via Pinzo &lt;${getRawFromEmail()}&gt;</p>
234	          ${options?.replyTo ? `<p style="color:#374151"><strong>Reply-To:</strong> ${options.replyTo}</p>` : '<p style="color:#374151"><strong>Reply-To:</strong> <em>Not set</em></p>'}
235	          <p style="color:#6b7280;font-size:13px;margin-top:24px">You will receive notifications when customers join your waitlist.</p>
236	      `),
237	      text: `Test email received!\n\nYour email integration is working correctly.\n\nFrom: ${name} via Pinzo <${getRawFromEmail()}>\nReply-To: ${options?.replyTo || "Not set"}\n\nYou will receive notifications when customers join your waitlist.`,
238	      ...buildReplyTo(options),
239	    });
240	    return true;
241	  } catch (error) {
242	    console.error("[email] Failed to send test email:", error);
243	    return false;
244	  }
245	}
