96	<div
97	  id="zcc-widget-{{ block.id }}"
98	  data-zcc-widget="true"
99	  data-shop="{{ shop.permanent_domain }}"
100	  data-api="{{ app.url }}"
101	  data-proxy="/apps/zipcheck"
102	  data-block="{{ block.id }}"
103	  {{ block.shopify_attributes }}
104	></div>
105	
106	<script>
107	(function () {
108	  // Wait for app embed to set window.__zccAppEnabled.
109	  // App embed (target: body) may load after this section block, so we poll briefly.
110	  var maxWait = 3000; // ms
111	  var interval = 50;  // ms
112	  var elapsed = 0;
113	
114	  function tryInit() {
115	    if (window.__zccAppEnabled) {
116	      init();
117	    } else if (elapsed < maxWait) {
118	      elapsed += interval;
119	      setTimeout(tryInit, interval);
120	    }
121	    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
122	  }
123	
124	  // Start checking — if already set, runs immediately
125	  if (document.readyState === 'loading') {
126	    document.addEventListener('DOMContentLoaded', tryInit);
127	  } else {
128	    tryInit();
129	  }
130	
131	  function init() {
132	  var ROOT_ID = "zcc-widget-{{ block.id }}";
133	  var container = document.getElementById(ROOT_ID);
134	  if (!container) return;
135	
136	  var SHOP = container.dataset.shop;
137	  // app.url resolves to the App Proxy URL (e.g. https://store.myshopify.com/apps/zipcheck).
138	  // If for any reason it is empty (e.g. dev environment or Shopify Liquid context issue),
139	  // fall back to the relative proxy path so the request still routes correctly through
140	  // Shopify's App Proxy rather than hitting the store's own domain as a missing route.
141	  var _rawApi = (container.dataset.api || "").replace(/\/$/, "");
142	  var _proxyPath = (container.dataset.proxy || "/apps/zipcheck").replace(/\/$/, "");
143	  // Prefer app.url when it looks like a full URL; otherwise use the relative proxy path
144	  // (which Shopify will forward to our app via the App Proxy config).
145	  var API_BASE = (_rawApi && _rawApi.indexOf("http") === 0) ? _rawApi : _proxyPath;
146	
147	  // ── Pre-lock: applied synchronously BEFORE the async config fetch ────────────
148	  // This eliminates the race window where ATC/Buy Now buttons are clickable
149	  // while the config fetch is in flight (typically 100–500 ms).
150	  // renderWidget() will call _zccUnlock() immediately if the feature is
151	  // disabled (lockButtonsUntilZipCheck:false) or position is "inline".
152	  var _zccLockStyleId = 'zcc-lock-style';
153	  function _zccInjectLockCss() {
154	    if (document.getElementById(_zccLockStyleId)) return;
155	    var s = document.createElement('style');
156	    s.id = _zccLockStyleId;
157	    s.textContent =
158	      'html[data-zcc-locked] form[action*="/cart/add"] button[type="submit"],' +
159	      'html[data-zcc-locked] button[name="add"],' +
160	      'html[data-zcc-locked] .product-form__submit,' +
161	      'html[data-zcc-locked] [data-product-add],' +
162	      'html[data-zcc-locked] .btn--add-to-cart,' +
163	      'html[data-zcc-locked] .product-form button[type="submit"],' +
164	      'html[data-zcc-locked] button.product-form__cart-submit,' +
165	      'html[data-zcc-locked] .product__submit button[type="submit"],' +
166	      'html[data-zcc-locked] .pdp-form button[type="submit"]' +
167	      '{opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
168	      'html[data-zcc-locked] .shopify-payment-button,' +
169	      'html[data-zcc-locked] [data-shopify="payment-button"],' +
170	      'html[data-zcc-locked] .shopify-payment-button__button--unbranded' +
171	      '{position:relative!important;opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
172	      'html[data-zcc-locked] .shopify-payment-button::after,' +
173	      'html[data-zcc-locked] [data-shopify="payment-button"]::after' +
174	      '{content:""!important;position:absolute!important;inset:0!important;z-index:2147483647!important;cursor:not-allowed!important;background:transparent!important;}';
175	    (document.head || document.documentElement).appendChild(s);
176	  }
177	  function _zccLock() {
178	    _zccInjectLockCss();
179	    document.documentElement.setAttribute('data-zcc-locked', '1');
180	  }
181	  function _zccUnlock() {
182	    document.documentElement.removeAttribute('data-zcc-locked');
183	  }
184	  // Lock immediately — but skip if the customer already validated this shop's
185	  // ZIP in this session (avoids flash-of-disabled-buttons on page refresh).
186	  var _priorValid = false;
187	  try {
188	    _priorValid = sessionStorage.getItem('zcc:valid') === 'true' &&
189	                  sessionStorage.getItem('zcc:shop') === SHOP;
190	  } catch(e) {}
191	  if (!_priorValid) {
192	    _zccLock();
193	  }
194	
195	  // Always fetch fresh config from the API so color/setting changes made in the
196	  // admin are reflected on the storefront immediately. The metafield-embedded
197	  // data-config attribute is intentionally ignored here: it is baked into
198	  // Shopify's CDN-cached HTML at render time and can be stale for many minutes
199	  // after a merchant saves new settings. The API endpoint returns
200	  // Cache-Control: no-store so it is always up to date.
201	  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
202	    .then(function (r) {
203	      if (!r.ok) throw new Error("Widget config API returned " + r.status);
204	      return r.json();
205	    })
206	    .then(function (cfg) { renderWidget(cfg); })
207	    .catch(function (err) {
208	      console.warn("[Pinzo] Could not load widget config, using defaults:", err.message || err);
209	      renderWidget({});
210	    });
211	
212	  function renderWidget(cfg) {
213	    // Merge with defaults
214	    var D = {
215	      position: "inline",
216	      heading: "Check Delivery Availability",
217	      placeholder: "Enter your zip code",
218	      buttonText: "Check",
219	      successMessage: "Great news! We deliver to your area.",
220	      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
221	      notFoundMessage: "We currently do not ship to this ZIP code.",
222	      primaryColor: "#008060",
223	      successColor: "#008060",
224	      errorColor: "#D72C0D",
225	      backgroundColor: "#FFFFFF",
226	      textColor: "#202223",
227	      borderRadius: "8",
228	      showEta: true,
229	      showZone: false,
230	      showWaitlistOnFailure: false,
231	      showCod: true,
232	      showReturnPolicy: true,
233	      showCutoffTime: true,
234	      showDeliveryDays: true,
235	      showDeliveryDate: true,
236	      showCountdown: true,
237	      showDeliveryFee: true,
238	      customCss: "",
239	      blockCartOnInvalid: false,
240	      showSocialProof: true,
241	    };
242	    // Default lockButtonsUntilZipCheck to true
