20	function calculateDeliveryDate(
21	  estimatedDays: string,
22	  daysOfWeek: string | null,
23	): string | null {
24	  const match = estimatedDays.match(/^(\d+)/);
25	  if (!match) return null;
26	  const minDays = parseInt(match[1], 10);
27	  if (isNaN(minDays) || minDays < 0) return null;
28	
29	  const deliveryDayNames = daysOfWeek
30	    ? daysOfWeek.split(",").map((d) => d.trim().toLowerCase())
31	    : ["mon", "tue", "wed", "thu", "fri"];
32	
33	  const dayMap: Record<string, number> = {
34	    sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6,
35	  };
36	  const deliveryDayNumbers = new Set(
37	    deliveryDayNames.map((d) => dayMap[d]).filter((n) => n !== undefined),
38	  );
39	
40	  if (deliveryDayNumbers.size === 0) {
41	    [1, 2, 3, 4, 5].forEach((d) => deliveryDayNumbers.add(d));
42	  }
43	
44	  const date = new Date();
45	  let businessDaysAdded = 0;
46	
47	  while (businessDaysAdded < minDays) {
48	    date.setDate(date.getDate() + 1);
49	    if (deliveryDayNumbers.has(date.getDay())) {
50	      businessDaysAdded++;
51	    }
52	  }
53	
54	  while (!deliveryDayNumbers.has(date.getDay())) {
55	    date.setDate(date.getDate() + 1);
56	  }
57	
58	  return date.toISOString().split("T")[0];
59	}
