82	const SHOP_DOMAIN_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;
83	
84	async function handleZipCheck(shop: string | null, zip: string | null) {
85	  if (!shop || !zip) {
86	    return new Response(
87	      JSON.stringify({ error: "Missing shop or zip parameter" }),
88	      { status: 400, headers: CORS_HEADERS },
89	    );
90	  }
91	
92	  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
93	  if (!SHOP_DOMAIN_RE.test(shop) || shop.length > 100) {
94	    return new Response(
95	      JSON.stringify({ error: "Invalid shop parameter" }),
96	      { status: 400, headers: CORS_HEADERS },
97	    );
98	  }
99	
100	  // Enforce input length limits to prevent abuse
101	  if (zip.length > 20) {
102	    return new Response(
103	      JSON.stringify({ error: "Invalid zip code" }),
104	      { status: 400, headers: CORS_HEADERS },
105	    );
106	  }
107	
108	  const normalizedZip = normalizeZipCode(zip);
109	
110	  try {
111	  const zipRecord = await db.zipCode.findUnique({
112	    where: { shop_zipCode: { shop, zipCode: normalizedZip } },
113	  });
114	
115	  // Fetch widget config for custom messages (falls back to defaults)
116	  const widgetConfig = await db.widgetConfig.findUnique({ where: { shop } });
117	
118	  // Fetch shop settings to determine default behavior for unlisted zip codes
119	  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
120	  const defaultBehavior = shopSettings?.defaultBehavior ?? "block";
121	
122	  if (!zipRecord || !zipRecord.isActive) {
123	    const notFoundMsg =
124	      widgetConfig?.notFoundMessage ??
125	      "We currently do not ship to this ZIP code.";
126	
127	    // If the zip is simply not in the list (not inactive) and the merchant
128	    // has set defaultBehavior to "allow", treat it as an allowed zip
129	    if (!zipRecord && defaultBehavior === "allow") {
130	      const successMsg =
131	        widgetConfig?.successMessage ?? "We deliver to your area!";
132	      return new Response(
133	        JSON.stringify({
134	          allowed: true,
135	          message: successMsg,
136	          eta: null,
137	          zone: null,
138	          codAvailable: null,
139	          returnPolicy: null,
140	          showWaitlist: false,
141	          waitlistCount: 0,
142	          cutoffTime: null,
143	          daysOfWeek: null,
144	        }),
145	        { status: 200, headers: SUCCESS_HEADERS },
146	      );
147	    }
148	
149	    // Social proof: count how many customers are waiting for this ZIP
150	    let waitlistCount = 0;
151	    try {
152	      waitlistCount = await db.waitlistEntry.count({
153	        where: { shop, zipCode: normalizedZip, status: "waiting" },
154	      });
155	    } catch {
156	      waitlistCount = 0;
157	    }
158	
159	    if (!zipRecord) {
160	      return new Response(
161	        JSON.stringify({
162	          allowed: false,
163	          message: notFoundMsg,
164	          notFound: true,
165	          showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
166	          waitlistCount,
167	        }),
168	        { status: 200, headers: DENY_HEADERS },
169	      );
170	    }
171	
172	    // Inactive zip — treat same as not found regardless of defaultBehavior
173	    return new Response(
174	      JSON.stringify({
175	        allowed: false,
176	        message: notFoundMsg,
177	        notFound: true,
178	        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
179	        waitlistCount,
180	      }),
181	      { status: 200, headers: DENY_HEADERS },
182	    );
183	  }
184	
185	  if (zipRecord.type === "blocked") {
186	    const errorMsg =
187	      zipRecord.message ??
188	      widgetConfig?.errorMessage ??
189	      "Sorry, we don't deliver to this area yet.";
190	
191	    // Social proof: count how many customers are waiting for this ZIP
192	    let waitlistCount = 0;
193	    try {
194	      waitlistCount = await db.waitlistEntry.count({
195	        where: { shop, zipCode: normalizedZip, status: "waiting" },
196	      });
197	    } catch {
198	      waitlistCount = 0;
199	    }
200	
201	    return new Response(
202	      JSON.stringify({
203	        allowed: false,
204	        message: errorMsg,
205	        showWaitlist: widgetConfig?.showWaitlistOnFailure ?? false,
206	        waitlistCount,
207	      }),
208	      { status: 200, headers: DENY_HEADERS },
209	    );
210	  }
211	
212	  // Fetch the most relevant active DeliveryRule for this zip.
213	  // Priority 1: rules that explicitly list this zip in their zipCodes field.
214	  // Priority 2: rules that match by zone (with no explicit zip list).
215	  // Within each priority tier, order by `priority ASC` (lower = higher priority).
216	  const zipCodeUpper = normalizedZip;
217	  const zipZone = zipRecord.zone ?? null;
218	
219	  // Fetch all active rules for the shop ordered by priority so we can apply
220	  // the matching logic in a single query result.
221	  const activeRules = await db.deliveryRule.findMany({
222	    where: { shop, isActive: true },
223	    orderBy: { priority: "asc" },
224	  });
225	
226	  let matchedRule: (typeof activeRules)[number] | null = null;
227	
228	  // Pass 1: explicit zip match — zipCodes field contains this zip code
229	  for (const rule of activeRules) {
230	    if (rule.zipCodes) {
231	      const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
232	      if (zips.includes(zipCodeUpper)) {
233	        matchedRule = rule;
234	        break;
235	      }
236	    }
237	  }
238	
239	  // Pass 2: zone match — rule's zone matches the zip's zone and no explicit zip list
240	  if (!matchedRule && zipZone) {
241	    for (const rule of activeRules) {
242	      if (
243	        rule.zone === zipZone &&
244	        (!rule.zipCodes || rule.zipCodes.trim() === "")
245	      ) {
246	        matchedRule = rule;
247	        break;
248	      }
249	    }
250	  }
251	
252	  // Allowed
253	  const successMsg =
254	    zipRecord.message ??
255	    widgetConfig?.successMessage ??
256	    "Great news! We deliver to your area.";
257	
258	  // ETA: prefer the zip-level eta, then fall back to the matched delivery rule's
259	  // estimatedDays so merchants only need to populate one place.
260	  const etaValue = zipRecord.eta ?? matchedRule?.estimatedDays ?? null;
261	
262	  const estimatedDeliveryDate =
263	    widgetConfig?.showDeliveryDate !== false && etaValue
264	      ? calculateDeliveryDate(etaValue, matchedRule?.daysOfWeek ?? null)
265	      : null;
266	
267	  const rawDeliveryFee = widgetConfig?.showDeliveryFee !== false ? (matchedRule?.deliveryFee ?? null) : null;
268	  const deliveryFeeValue = rawDeliveryFee != null && rawDeliveryFee >= 0 ? rawDeliveryFee : null;
269	  const rawFreeShippingAbove = widgetConfig?.showDeliveryFee !== false ? (matchedRule?.freeShippingAbove ?? null) : null;
270	  const freeShippingAboveValue = rawFreeShippingAbove != null && rawFreeShippingAbove >= 0 ? rawFreeShippingAbove : null;
271	
272	  return new Response(
273	    JSON.stringify({
274	      allowed: true,
275	      message: successMsg,
276	      eta: widgetConfig?.showEta ? etaValue : null,
277	      zone: widgetConfig?.showZone ? (zipRecord.zone ?? null) : null,
278	      codAvailable: widgetConfig?.showCod !== false ? (zipRecord.codAvailable ?? null) : null,
279	      returnPolicy: widgetConfig?.showReturnPolicy !== false ? (zipRecord.returnPolicy ?? null) : null,
280	      showWaitlist: false,
281	      waitlistCount: 0,
282	      cutoffTime: widgetConfig?.showCutoffTime !== false ? (matchedRule?.cutoffTime ?? null) : null,
283	      daysOfWeek: widgetConfig?.showDeliveryDays !== false ? (matchedRule?.daysOfWeek ?? null) : null,
284	      estimatedDeliveryDate,
285	      deliveryFee: deliveryFeeValue,
286	      freeShippingAbove: freeShippingAboveValue,
287	    }),
288	    { status: 200, headers: SUCCESS_HEADERS },
289	  );
290	  } catch (err) {
291	    console.error("[api.zip-check] Unhandled error for shop=%s zip=%s:", shop, zip, err);
292	    return new Response(
293	      JSON.stringify({ error: "Internal server error" }),
294	      { status: 500, headers: CORS_HEADERS },
295	    );
296	  }
297	}
