438	  function formatDeliveryDate(isoDate) {
439	    if (!isoDate) return null;
440	    try {
441	      var parts = isoDate.split('-');
442	      var d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
443	      var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
444	      var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
445	      return days[d.getDay()] + ', ' + months[d.getMonth()] + ' ' + d.getDate();
446	    } catch(e) { return null; }
447	  }
